#include <multiset>
#include <iostream>
#include <functional>

int main() {
    // Defines the container to sort in descending order (6, 5, 5, 4, ...)
    using IntSet = std::multiset<int, std::greater<int>>;
    IntSet coll1;
    coll1.insert(4);
    coll1.insert(6);
    coll1.insert(5);

    // Output will be 6 5 4
    for (int x : coll1) {
        std::cout << x << ' ';
    }
    std::cout << "\n";
}
